code.cpp:
class Solution {
public:
    int getMaximumConsecutive(vector<int>& coins) {
        sort(coins.begin(), coins.end());
        long long x = 0;
        for (int c : coins) {
            if (c > x + 1) break;
            x += c;
        }
        return (int)(x + 1);
    }
};
